    TR("pt-nl","Quero ir a Amesterdão.", ["Ik wil naar Amsterdam","Ik wil naar Amsterdam gaan"], "willen + naar.", ["v-wil"]),
    DL([("Kind","Mag ik een ijsje?","Posso ter um gelado?"),("Vader","","")], ["*Ja hoor, dat mag, maar alleen één.","Ja, ik kan het.|Não responde.","Nee, je moet naar ijsje.|Errado."], "Dar permissão.", ["v-dat-mag"]),
    FE(["Ik","moet","morgen","naar","de","dokter","gegaan."], 6, "gaan", "Se o verbo aparece, é infinitivo: moet … gaan (ou omite-se).", ["v-naar-huis-moeten"]),
    FB("Ik ___ om acht uur op mijn werk zijn.", ["moet"], "Obrigação.", ["v-naar-huis-moeten"], choices=["moet","mag","hoef"], tr="Tenho de estar no trabalho às oito."),
    LI("Ik kan het niet, het is te moeilijk.", ["Ik kan het niet, het is te moeilijk","Ik kan het niet het is te moeilijk"], "Não consigo, é demasiado difícil.", "kunnen + het.", ["v-ik-kan-het"]),
    WO("Tenho de ir ao médico amanhã.", ["Ik","moet","morgen","naar","de","dokter"], "Sem «gaan».", ["v-naar-huis-moeten"]),
