L(20, "Modais na subordinada", "Ik weet niet of ik mag komen.",
  ["Pôr modal e infinitivo no fim de orações subordinadas"],
  vocab=[V("v-of-ik-mag","of ik mag …","se posso …","expression"), V("v-omdat-ik-moet","omdat ik … moet","porque tenho de …","expression"),
         V("v-zodat","zodat","para que|de modo que","conjunction")],
  ex=[("Ik weet niet of ik zaterdag mag komen.","Não sei se posso ir no sábado."),("Ik ben moe, omdat ik vroeg moest opstaan.","Estou cansado porque tive de me levantar cedo."),("Ik spreek langzaam, zodat iedereen het kan volgen.","Falo devagar para que todos possam acompanhar.")],
  review=["v-omdat","v-of-conj"],
  gram=[G("g-modaal-bijzin","Modal na oração subordinada","Na subordinada (com *dat, omdat, of, als, zodat…*) **todos os verbos vão para o fim**, normalmente com o modal antes do infinitivo: *…omdat ik morgen **moet werken**.* Também é correta a ordem *…omdat ik morgen werken moet*, mas a primeira é mais frequente.",
    [("Ze zegt dat ze niet kan komen.","Ela diz que não pode vir."),("Bel me als je hulp nodig hebt.","Liga-me se precisares de ajuda.")])],
  cefr=C, exs=[
    MA([("of ik mag …","se posso …"),("omdat ik … moet","porque tenho de …"),("zodat","para que"),("dat","que")], "Subordinadas.", ["v-of-ik-mag","v-omdat-ik-moet","v-zodat","v-omdat"]),
    MC("Qual é a ordem certa?", ["*Ik weet niet of ik mag komen.","Ik weet niet of ik komen mag niet.|Errado.","Ik weet niet of mag ik komen.|Na subordinada, verbos no fim."], "Verbos no fim.", ["v-of-ik-mag"]),
    BS("Estou cansado porque tive de trabalhar até tarde.", ["Ik","ben","moe,","omdat","ik","tot","laat","moest","werken","werkte"], ["Ik ben moe, omdat ik tot laat moest werken"], "omdat + verbos no fim.", ["v-omdat-ik-moet"]),
    BS("Falo devagar para que todos possam acompanhar.", ["Ik","spreek","langzaam,","zodat","iedereen","het","kan","volgen","volgt"], ["Ik spreek langzaam, zodat iedereen het kan volgen"], "zodat + verbos no fim.", ["v-zodat"]),
    TR("pt-nl","Não sei se posso ir no sábado.", ["Ik weet niet of ik zaterdag mag komen","Ik weet niet of ik zaterdag kan komen"], "of + verbos no fim.", ["v-of-ik-mag"]),
    MC("Qual é a ordem correta?", ["*Ze zegt dat ze niet kan komen.","Ze zegt dat ze kan niet komen.|Ordem: …dat ze niet kan komen."], "Ordem: …dat ze niet kan komen.", ["v-of-ik-mag"]),
    FB("Ik neem een taxi, ___ ik op tijd ben.", ["zodat"], "Para que.", ["v-zodat"], choices=["zodat","omdat","want"], tr="Apanho um táxi para chegar a horas."),
    MC("«Zodat» indica…", ["*finalidade/consequência (para que)","causa (porque)|Isso é omdat.","tempo (quando)|Isso é als/toen."], "zodat.", ["v-zodat"]),
    LI("Ik weet niet of ik morgen mag thuiswerken.", ["Ik weet niet of ik morgen mag thuiswerken"], "Não sei se amanhã posso trabalhar em casa.", "Verbos no fim.", ["v-of-ik-mag"]),
    WO("Ela diz que não pode vir.", ["Ze","zegt","dat","ze","niet","kan","komen"], "Verbos no fim.", ["v-of-ik-mag"]),
  ], diff=4, mins=7)

L(21, "Prática: as regras do trabalho", "Wat moet, mag, kan en hoeft?",
  ["Explicar as regras de um local de trabalho usando todos os modais"],
  vocab=[V("v-werktijden","werktijden","horário de trabalho","noun","de"), V("v-flexibel-werken","flexibel werken","trabalhar com horário flexível","expression"),
         V("v-afmelden","zich afmelden","avisar que não vem|cancelar presença","verb")],
  ex=[("De werktijden zijn flexibel.","O horário de trabalho é flexível."),("Bij ons mag je flexibel werken.","Connosco podes trabalhar com horário flexível."),("Je moet je voor negen uur afmelden.","Tens de avisar antes das nove que não vens.")],
  review=["v-moeten","v-mag","v-hoeven","v-kun","v-regel"],
  cefr=C, exs=[
    MA([("werktijden","horário de trabalho"),("flexibel werken","horário flexível"),("zich afmelden","avisar que não vem"),("regel","regra")], "Regras de trabalho.", ["v-werktijden","v-flexibel-werken","v-afmelden","v-regel"]),
    CO("text","Welkom! De belangrijkste afspraken", "- Je mag flexibel werken: je kunt tussen 7.00 en 10.00 uur beginnen.\n- Je moet wel elke dag tussen 10.00 en 15.00 uur bereikbaar zijn.\n- Je mag twee dagen per week thuiswerken.\n- Ben je ziek? Dan moet je je vóór 9.00 uur telefonisch afmelden bij je leidinggevende.\n- Je hoeft geen pak te dragen; netjes is genoeg.\n- Lunch kun je in de kantine kopen of zelf meenemen.",
       [("Quando se pode começar?", ["*Entre as 7h e as 10h","Às 9h em ponto","Quando se quiser"]),("Quantos dias de teletrabalho?", ["*Dois por semana","Nenhum","Todos"]),("É preciso usar fato?", ["*Não, basta estar apresentável","Sim","Só às segundas"])],
       "Todos os modais num texto real.", ["v-werktijden","v-flexibel-werken","v-afmelden"]),
    MC("«Je hoeft geen pak te dragen» significa…", ["*Não é preciso usar fato","É proibido usar fato|Seria «mag niet».","Tens de usar fato|É o contrário."], "hoeven.", ["v-hoeven"]),
    TR("pt-nl","Podes trabalhar em casa dois dias por semana.", ["Je mag twee dagen per week thuiswerken","Je kunt twee dagen per week thuiswerken"], "mogen = permissão.", ["v-mag"]),
    TR("pt-nl","Tens de avisar antes das nove.", ["Je moet je voor negen uur afmelden","Je moet je vóór negen uur afmelden","Je moet je voor 9 uur afmelden"], "zich afmelden.", ["v-afmelden"]),
    FE(["Je","hoeft","geen","pak","dragen."], 4, "te dragen", "hoeven + te.", ["v-hoeven"]),
    FB("Bij ons ___ je zelf je werktijden kiezen.", ["mag"], "Permissão.", ["v-flexibel-werken"], choices=["mag","moet","hoeft"], tr="Connosco podes escolher tu o teu horário."),
    AR("werktijd","o horário","de", "De tijd → de werktijd.", ["v-werktijden"]),
    LI("Je moet wel tussen tien en drie bereikbaar zijn.", ["Je moet wel tussen tien en drie bereikbaar zijn"], "Mas tens de estar contactável entre as dez e as três.", "wel = mas (contraste).", ["v-werktijden"]),
    SW("Explique 5 regras da sua casa, escola ou trabalho usando moeten, mogen, niet mogen, kunnen e niet hoeven te.", ["Bij ons thuis moet iedereen zijn eigen bord afwassen. De kinderen mogen tot negen uur tv kijken. Je mag niet met schoenen in de woonkamer lopen. Je kunt altijd iets uit de koelkast pakken. Op zondag hoef je niet vroeg op te staan."], ["moeten", "mogen e niet mogen", "kunnen", "niet hoeven te"], 40, "Regras com modais.", ["v-regel","v-werktijden"]),
  ], diff=4, mins=8)

W()
